#include "c1001_protocol.h"

#include <array>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <limits>

using sleep_radar::Frame;
using sleep_radar::Parser;

namespace {

// Independently calculated reference frames, not generated by the encoder.
constexpr std::array<std::uint8_t, 10> kHeartQuery{
    0x53, 0x59, 0x85, 0x82, 0x00, 0x01, 0x0F, 0xC3, 0x54, 0x43};
constexpr std::array<std::uint8_t, 10> kHeartResponse{
    0x53, 0x59, 0x85, 0x82, 0x00, 0x01, 0x48, 0xFC, 0x54, 0x43};

bool sameFrame(const Frame& left, const Frame& right) {
    return left.control == right.control && left.command == right.command &&
           left.length == right.length && left.payload == right.payload;
}

Frame sentinel() {
    Frame frame{};
    frame.control = 0xBE;
    frame.command = 0xEF;
    frame.length = 64;
    frame.payload.fill(0xAD);
    return frame;
}

template <std::size_t N>
unsigned feedBytes(Parser& parser, const std::array<std::uint8_t, N>& bytes,
                   std::uint32_t& now, Frame& out) {
    unsigned frames = 0;
    for (auto byte : bytes) {
        if (parser.feed(byte, now++, out)) {
            ++frames;
        }
    }
    return frames;
}

void checkHeart(const Frame& frame) {
    assert(frame.control == 0x85);
    // The official query response repeats 0x82; it is not changed to 0x02.
    assert(frame.command == 0x82);
    assert(frame.length == 1);
    assert(frame.payload[0] == 72);
    for (std::size_t i = 1; i < frame.payload.size(); ++i) {
        assert(frame.payload[i] == 0);
    }
}

void testQueryAndEncoder() {
    const auto request = sleep_radar::query(0x85, 0x82);
    assert(request.length == 1 && request.payload[0] == 0x0F);
    std::array<std::uint8_t, 10> encoded{};
    assert(sleep_radar::encodeFrame(request, encoded.data(), encoded.size()) == 10);
    assert(encoded == kHeartQuery);

    // query() never silently turns a write command into a query command.
    assert(sleep_radar::query(0x84, 0x0F).command == 0x0F);

    encoded.fill(0xA5);
    const auto before = encoded;
    assert(sleep_radar::encodeFrame(request, encoded.data(), 9) == 0);
    assert(encoded == before);
    assert(sleep_radar::encodeFrame(request, nullptr, 100) == 0);
    Frame too_large{};
    too_large.length = 65;
    assert(sleep_radar::encodeFrame(too_large, encoded.data(), 100) == 0);
    assert(encoded == before);
    too_large.length = std::numeric_limits<std::uint16_t>::max();
    assert(sleep_radar::encodeFrame(too_large, encoded.data(), 100) == 0);
}

void testFragmentationAndBackToBack() {
    Parser parser;
    Frame out = sentinel();
    const Frame before = out;
    std::uint32_t now = 0;
    for (std::size_t i = 0; i < kHeartResponse.size(); ++i) {
        if (i == 3 || i == 7) {
            now += sleep_radar::kInterByteTimeoutMs - 2;
            parser.tick(now);
        }
        const bool complete = parser.feed(kHeartResponse[i], now++, out);
        assert(complete == (i + 1 == kHeartResponse.size()));
        if (!complete) {
            assert(sameFrame(out, before));
        }
    }
    checkHeart(out);
    assert(feedBytes(parser, kHeartResponse, now, out) == 1);
    assert(parser.stats().frames == 2);
    assert(parser.stats().timeouts == 0);
    parser.tick(now + 10000);
    assert(parser.stats().timeouts == 0);
}

void testNoiseAndOverlappingHeaders() {
    Parser parser;
    Frame out{};
    std::uint32_t now = 0;
    constexpr std::array<std::uint8_t, 9> noise{
        0x00, 0x59, 0x54, 0x43, 0xFF, 0x53, 0x00, 0x53, 0x53};
    assert(feedBytes(parser, noise, now, out) == 0);
    assert(feedBytes(parser, kHeartResponse, now, out) == 1);
    checkHeart(out);
    assert(parser.stats().checksum_errors == 0);
    assert(parser.stats().framing_errors == 0);
}

void testBadChecksumAndBothTailBytes() {
    for (std::size_t broken_index : {7U, 8U, 9U}) {
        Parser parser;
        auto broken = kHeartResponse;
        broken[broken_index] ^= 0x01;
        Frame out = sentinel();
        const Frame before = out;
        std::uint32_t now = 0;
        assert(feedBytes(parser, broken, now, out) == 0);
        assert(sameFrame(out, before));
        assert(parser.stats().checksum_errors == (broken_index == 7 ? 1U : 0U));
        assert(parser.stats().framing_errors == (broken_index == 7 ? 0U : 1U));
        assert(feedBytes(parser, kHeartResponse, now, out) == 1);
        checkHeart(out);
    }

    // A broken tail may itself be the first byte of the next frame.
    for (std::size_t kept : {8U, 9U}) {
        Parser parser;
        Frame out{};
        std::uint32_t now = 0;
        for (std::size_t i = 0; i < kept; ++i) {
            assert(!parser.feed(kHeartResponse[i], now++, out));
        }
        assert(feedBytes(parser, kHeartResponse, now, out) == 1);
        checkHeart(out);
        assert(parser.stats().framing_errors == 1);
    }
}

void testInvalidLengths() {
    for (const auto length_bytes : {
             std::array<std::uint8_t, 2>{0x00, 0x41},
             std::array<std::uint8_t, 2>{0x01, 0x00},
             std::array<std::uint8_t, 2>{0xFF, 0xFF}}) {
        Parser parser;
        const std::array<std::uint8_t, 6> oversized{
            0x53, 0x59, 0x85, 0x82, length_bytes[0], length_bytes[1]};
        Frame out{};
        std::uint32_t now = 0;
        assert(feedBytes(parser, oversized, now, out) == 0);
        assert(parser.stats().length_errors == 1);
        assert(feedBytes(parser, kHeartResponse, now, out) == 1);
        checkHeart(out);
    }
}

void testZeroAndMaximumPayload() {
    Parser parser;
    Frame out{};
    std::uint32_t now = 0;
    // Length 0 is accepted by the transport even though queries use length 1.
    constexpr std::array<std::uint8_t, 9> empty{
        0x53, 0x59, 0x00, 0x00, 0x00, 0x00, 0xAC, 0x54, 0x43};
    assert(feedBytes(parser, empty, now, out) == 1);
    assert(out.length == 0);

    Frame maximum{};
    maximum.control = 0xFF;
    maximum.command = 0xFE;
    maximum.length = sleep_radar::kMaxPayload;
    maximum.payload.fill(0xFF);
    // Header and tail patterns inside valid data must not cause resync.
    maximum.payload[0] = 0x53;
    maximum.payload[1] = 0x59;
    maximum.payload[62] = 0x54;
    maximum.payload[63] = 0x43;
    std::array<std::uint8_t, sleep_radar::kMaxFrameSize> bytes{};
    assert(sleep_radar::encodeFrame(maximum, bytes.data(), bytes.size()) == 73);
    assert(bytes[4] == 0 && bytes[5] == 64);
    std::uint32_t sum = 0;
    for (std::size_t i = 0; i < 70; ++i) {
        sum += bytes[i];
    }
    assert(bytes[70] == (sum & 0xFF));
    assert(feedBytes(parser, bytes, now, out) == 1);
    assert(sameFrame(out, maximum));
}

void testBufferedRecovery() {
    Parser parser;
    Frame out{};
    std::uint32_t now = 0;
    // A corrupt candidate with a plausible length encloses a complete frame.
    constexpr std::array<std::uint8_t, 6> false_header{
        0x53, 0x59, 0x01, 0x02, 0x00, 0x0A};
    assert(feedBytes(parser, false_header, now, out) == 0);
    assert(feedBytes(parser, kHeartResponse, now, out) == 0);
    assert(parser.feed(0x00, now++, out));  // Invalid outer checksum.
    checkHeart(out);
    assert(parser.stats().checksum_errors == 1);
    assert(feedBytes(parser, kHeartResponse, now, out) == 1);
}

void testTimeoutAndRollover() {
    Parser parser;
    Frame out = sentinel();
    const Frame before = out;
    const std::uint32_t start = std::numeric_limits<std::uint32_t>::max() - 50U;
    assert(!parser.feed(0x53, start, out));
    parser.tick(start + sleep_radar::kInterByteTimeoutMs - 1U);
    assert(parser.stats().timeouts == 0);
    parser.tick(start + sleep_radar::kInterByteTimeoutMs);
    assert(parser.stats().timeouts == 1);
    assert(sameFrame(out, before));
    parser.tick(start + sleep_radar::kInterByteTimeoutMs + 1000U);
    assert(parser.stats().timeouts == 1);

    std::uint32_t now = 200;
    assert(feedBytes(parser, kHeartResponse, now, out) == 1);
    checkHeart(out);
    parser.reset();
    assert(parser.stats().frames == 1 && parser.stats().timeouts == 1);

    // An entire valid frame may cross rollover without timing out.
    now = std::numeric_limits<std::uint32_t>::max() - 4U;
    assert(feedBytes(parser, kHeartResponse, now, out) == 1);
    assert(parser.stats().timeouts == 1);
    checkHeart(out);

    // feed() performs timeout maintenance itself and retains the new sync byte.
    assert(!parser.feed(0x53, 500, out));
    now = 500 + sleep_radar::kInterByteTimeoutMs;
    assert(feedBytes(parser, kHeartResponse, now, out) == 1);
    assert(parser.stats().timeouts == 2);
}

void testLengthSweepAndNoiseStream() {
    Parser parser;
    Frame out{};
    std::uint32_t now = 0;
    for (std::uint16_t length = 0; length <= sleep_radar::kMaxPayload; ++length) {
        Frame expected{};
        expected.control = static_cast<std::uint8_t>(length);
        expected.command = static_cast<std::uint8_t>(length + 128);
        expected.length = length;
        for (std::uint16_t i = 0; i < length; ++i) {
            expected.payload[i] = static_cast<std::uint8_t>((i * 197U) + length);
        }
        std::array<std::uint8_t, sleep_radar::kMaxFrameSize> bytes{};
        const auto size = sleep_radar::encodeFrame(expected, bytes.data(), bytes.size());
        for (auto noise : {0x00, 0xFF, 0x59, 0x54, 0x43}) {
            assert(!parser.feed(static_cast<std::uint8_t>(noise), now++, out));
        }
        for (std::size_t i = 0; i < size; ++i) {
            assert(parser.feed(bytes[i], now++, out) == (i + 1 == size));
        }
        assert(sameFrame(out, expected));
    }
    assert(parser.stats().frames == 65);
}

}  // namespace

int main() {
    testQueryAndEncoder();
    testFragmentationAndBackToBack();
    testNoiseAndOverlappingHeaders();
    testBadChecksumAndBothTailBytes();
    testInvalidLengths();
    testZeroAndMaximumPayload();
    testBufferedRecovery();
    testTimeoutAndRollover();
    testLengthSweepAndNoiseStream();
    std::cout << "C1001 protocol tests passed\n";
}
